package vazkii.botania.api.recipe;
import java.util.*; import net.minecraft.core.HolderLookup; import net.minecraft.core.NonNullList; import net.minecraft.world.item.ItemStack; import net.minecraft.world.item.crafting.Ingredient; import net.minecraft.world.item.crafting.Recipe; import net.minecraft.world.item.crafting.RecipeType; import net.minecraft.world.level.Level;
public interface ElvenTradeRecipe extends Recipe<ProcessingRecipeInput> { NonNullList<Ingredient> getIngredients(); List<ItemStack> getOutputs(); Optional<AssemblyResult> tryAssemble(ProcessingRecipeInput input,HolderLookup.Provider registries); default RecipeType<?> getType(){return null;} default boolean matches(ProcessingRecipeInput i,Level l){return tryAssemble(i,l.registryAccess()).isPresent();} default ItemStack assemble(ProcessingRecipeInput i,HolderLookup.Provider r){return tryAssemble(i,r).map(x->x.outputs().getFirst()).orElse(ItemStack.EMPTY);} default boolean canCraftInDimensions(int w,int h){return false;} default ItemStack getResultItem(HolderLookup.Provider r){return getOutputs().isEmpty()?ItemStack.EMPTY:getOutputs().getFirst();} record AssemblyResult(List<ItemStack> outputs,int matchedSlot){public AssemblyResult(ItemStack out,int slot){this(List.of(out),slot);}} }
